class Account {
    private int balance;          // campo: dato de cada objeto
    Account(int start) {          // constructor: corre cuando nace el objeto
        this.balance = start;
    }
    int balance() { return balance; }
}
Account a = new Account(10);
Account b = new Account(99);      // independiente de a

abstract class Game {
    final void play() {          // el orden es fijo
        start(); turn(); end();
    }
    void start() { }             // paso opcional
    abstract void turn();        // cada juego llena este
    void end() { }
}

class Car {
    private final Engine engine;      // tiene-un
    Car(Engine engine) { this.engine = engine; }
    void start() { engine.ignite(); } // delega
}

static int value() {
    int x = 1;
    try { x = 2; return x; }   // el resultado 2 se guarda antes
    finally { x = 3; }         // demasiado tarde para cambiarlo
}                              // devuelve 2

interface Priced { price: number }
class Book { constructor(public price: number) {} }
const items: Priced[] = [new Book(10), { price: 5 }];   // ambos se aceptan
